import { ListFilter, Plus } from '@gntik-ai/icons';
import {
  Button,
  cn,
  Menu,
  MenuCheckboxItem,
  MenuContent,
  MenuGroup,
  MenuGroupLabel,
  MenuSeparator,
  MenuTrigger,
  SearchField,
  SimpleSelect,
  Token,
  useI18n,
} from '@gntik-ai/ui';
import { Fragment, useState } from 'react';
import { DEPLOYMENT_DEFAULT_FILTERS, DEPLOYMENT_FILTER_FIELDS, DEPLOYMENT_SAVED_VIEWS } from './fixtures';
import { useDebouncedText } from './use-debounced-text';

export interface FilterField {
  id: string;
  label: string;
  options: readonly string[];
}

export interface ActiveFilter {
  field: string;
  value: string;
}

export interface SavedView {
  value: string;
  label: string;
  query?: string;
  filters: readonly ActiveFilter[];
}

export interface FilterBarLabels {
  searchLandmark: string;
  searchLabel: string;
  searchPlaceholder: string;
  savedViewLabel: string;
  savedViewPlaceholder: string;
  addFilter: string;
  activeFilters: string;
  filters: string;
  clearAll: string;
  removeFilter: (field: string, value: string) => string;
  resultCount: (count: number) => string;
}

export interface FilterBarProps {
  /** Per-key overrides take precedence over the legacy search props and provider catalog. */
  labels?: Partial<FilterBarLabels>;
  fields?: readonly FilterField[];
  /** Search text (controlled). */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /**
   * Milliseconds to wait after the last keystroke before calling `onQueryChange` (default 0: every keystroke).
   * The input still shows each keystroke at once; Enter, clearing, applying a view and unmount report at once.
   */
  queryDebounceMs?: number;
  /** Active filters (controlled). */
  filters?: readonly ActiveFilter[];
  defaultFilters?: readonly ActiveFilter[];
  onFiltersChange?: (filters: ActiveFilter[]) => void;
  /** Saved views; picking one applies its query and filters. Empty hides the Select. */
  views?: readonly SavedView[];
  defaultView?: string | null;
  onViewChange?: (view: SavedView) => void;
  searchLabel?: string;
  placeholder?: string;
  /** Optional result count shown at the end ("12 results"). */
  resultCount?: number;
  className?: string;
}

const same = (a: ActiveFilter, b: ActiveFilter) => a.field === b.field && a.value === b.value;

/**
 * Filter bar: SearchField, saved views Select, an "Add filter" Menu (multi-select per field),
 * removable filter chips (Token) and Clear all.
 */
export function FilterBar({
  fields = DEPLOYMENT_FILTER_FIELDS,
  query: queryProp,
  defaultQuery = '',
  onQueryChange,
  queryDebounceMs,
  filters: filtersProp,
  defaultFilters = DEPLOYMENT_DEFAULT_FILTERS,
  onFiltersChange,
  views = DEPLOYMENT_SAVED_VIEWS,
  defaultView = null,
  onViewChange,
  searchLabel: searchLabelProp,
  placeholder: placeholderProp,
  resultCount,
  className,
  labels,
}: FilterBarProps) {
  const { t } = useI18n();
  const searchLabel = labels?.searchLabel ?? searchLabelProp ?? t('common.search');
  const placeholder = labels?.searchPlaceholder ?? placeholderProp ?? 'Search by name…';
  const [innerQuery, setInnerQuery] = useState(defaultQuery);
  const [innerFilters, setInnerFilters] = useState<readonly ActiveFilter[]>(defaultFilters);
  const [view, setView] = useState<string | null>(defaultView);
  const query = queryProp ?? innerQuery;
  const filters = filtersProp ?? innerFilters;

  const setQuery = (next: string) => {
    setInnerQuery(next);
    onQueryChange?.(next);
  };
  const search = useDebouncedText(query, queryDebounceMs, setQuery);
  const setFilters = (next: ActiveFilter[], keepView = false) => {
    setInnerFilters(next);
    onFiltersChange?.(next);
    if (!keepView) setView(null);
  };
  const toggle = (filter: ActiveFilter, on: boolean) =>
    setFilters(on ? [...filters.filter((f) => !same(f, filter)), filter] : filters.filter((f) => !same(f, filter)));
  const applyView = (value: string | null) => {
    const picked = views.find((v) => v.value === value);
    if (!picked) return;
    setView(picked.value);
    setFilters([...picked.filters], true);
    // A view with a query replaces the pending text; one without leaves the text, so report what is pending now.
    if (picked.query !== undefined) search.replace(picked.query);
    else search.flush();
    onViewChange?.(picked);
  };
  const clearAll = () => {
    setFilters([]);
    search.replace('');
  };
  const labelOf = (id: string) => fields.find((f) => f.id === id)?.label ?? id;
  const hasAny = filters.length > 0 || search.text !== '';

  return (
    <div
      role="search"
      aria-label={labels?.searchLandmark ?? t('filters.label')}
      className={cn('flex flex-col gap-3', className)}
    >
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
        <SearchField
          aria-label={searchLabel}
          size="sm"
          placeholder={placeholder}
          value={search.text}
          onValueChange={(v) => search.change(String(v))}
          onSearch={(_, source) => (source === 'enter' ? search.flush() : undefined)}
          className="w-full sm:max-w-xs"
        />
        <div className="flex flex-wrap items-center gap-2">
          {views.length > 0 && (
            <SimpleSelect
              aria-label={labels?.savedViewLabel ?? t('filters.savedView')}
              size="sm"
              placeholder={labels?.savedViewPlaceholder ?? t('filters.savedViews')}
              value={view}
              onValueChange={applyView}
              items={views.map((v) => ({ value: v.value, label: v.label }))}
              className="min-w-[160px]"
            />
          )}
          <Menu>
            <MenuTrigger render={<Button variant="secondary" size="sm" icon={Plus} />}>
              {labels?.addFilter ?? t('filters.add')}
            </MenuTrigger>
            <MenuContent className="max-h-80 min-w-[220px] overflow-y-auto">
              {fields.map((field, i) => (
                <Fragment key={field.id}>
                  {i > 0 && <MenuSeparator />}
                  <MenuGroup>
                    <MenuGroupLabel>{field.label}</MenuGroupLabel>
                    {field.options.map((option) => {
                      const filter = { field: field.id, value: option };
                      return (
                        <MenuCheckboxItem
                          key={option}
                          checked={filters.some((f) => same(f, filter))}
                          onCheckedChange={(on) => toggle(filter, on)}
                        >
                          {option}
                        </MenuCheckboxItem>
                      );
                    })}
                  </MenuGroup>
                </Fragment>
              ))}
            </MenuContent>
          </Menu>
        </div>
        {resultCount !== undefined && (
          <p className="text-[12.5px] text-muted-foreground sm:ms-auto" aria-live="polite">
            {labels?.resultCount ? (
              labels.resultCount(resultCount)
            ) : (
              <>
                <span className="font-mono text-foreground tabular-nums">{resultCount.toLocaleString('en-US')}</span>{' '}
                {resultCount === 1 ? 'result' : 'results'}
              </>
            )}
          </p>
        )}
      </div>
      {hasAny && (
        <div className="flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center gap-1.5 font-mono text-[10px] tracking-[0.14em] text-muted-foreground label-case">
            <ListFilter size={12} aria-hidden />
            {labels?.filters ?? 'Filters'}
          </span>
          <ul aria-label={labels?.activeFilters ?? t('filters.active')} className="flex flex-wrap items-center gap-2">
            {filters.map((f) => (
              <li key={`${f.field}:${f.value}`} className="flex">
                <Token
                  size="sm"
                  prefix={`${labelOf(f.field)}:`}
                  label={f.value}
                  removeLabel={
                    labels?.removeFilter?.(labelOf(f.field), f.value) ??
                    t('filters.remove', { field: labelOf(f.field), value: f.value })
                  }
                  onRemove={() => toggle(f, false)}
                />
              </li>
            ))}
          </ul>
          <Button variant="ghost" size="sm" className="h-7 px-2 hover:text-destructive-text" onClick={clearAll}>
            {labels?.clearAll ?? 'Clear all'}
          </Button>
        </div>
      )}
    </div>
  );
}

import type { ActiveFilter, FilterField, SavedView } from './FilterBar';

export const DEPLOYMENT_FILTER_FIELDS: FilterField[] = [
  { id: 'status', label: 'Status', options: ['Running', 'Queued', 'Paused', 'Degraded', 'Failed'] },
  { id: 'region', label: 'Region', options: ['eu-west-1', 'us-east-1', 'ap-south-1', 'eu-central-1'] },
  { id: 'owner', label: 'Owner', options: ['Platform team', 'Payments team', 'Data team'] },
];

export const DEPLOYMENT_DEFAULT_FILTERS: ActiveFilter[] = [
  { field: 'status', value: 'Running' },
  { field: 'region', value: 'eu-west-1' },
];

export const DEPLOYMENT_SAVED_VIEWS: SavedView[] = [
  { value: 'all', label: 'All deployments', filters: [] },
  {
    value: 'attention',
    label: 'Needs attention',
    filters: [
      { field: 'status', value: 'Degraded' },
      { field: 'status', value: 'Failed' },
    ],
  },
  {
    value: 'eu',
    label: 'EU regions',
    filters: [
      { field: 'region', value: 'eu-west-1' },
      { field: 'region', value: 'eu-central-1' },
    ],
  },
];

import { useEffect, useRef, useState } from 'react';

/**
 * Text that shows every keystroke at once but reports it once typing pauses for `delayMs`. With no delay
 * every change is reported at once. `flush` reports the pending text now, `replace` sets and reports a
 * text now and drops the pending one, and an unmount reports what is still pending. A `value` changed
 * from outside replaces the draft and the pending text.
 */
export function useDebouncedText(value: string, delayMs: number | undefined, onCommit: (text: string) => void) {
  const debounced = delayMs !== undefined && delayMs > 0;
  const [draft, setDraft] = useState(value);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const pending = useRef<string | null>(null);
  const reported = useRef(value);
  const latest = useRef(onCommit);
  useEffect(() => {
    latest.current = onCommit;
  });

  const commit = (text: string) => {
    clearTimeout(timer.current);
    timer.current = undefined;
    pending.current = null;
    reported.current = text;
    latest.current(text);
  };
  useEffect(() => {
    if (value === reported.current) return;
    reported.current = value;
    clearTimeout(timer.current);
    timer.current = undefined;
    pending.current = null;
    setDraft(value);
  }, [value]);
  useEffect(
    () => () => {
      clearTimeout(timer.current);
      if (pending.current !== null) latest.current(pending.current);
    },
    [],
  );

  return {
    text: debounced ? draft : value,
    change: (next: string) => {
      if (!debounced) return commit(next);
      setDraft(next);
      clearTimeout(timer.current);
      // An emptied input reports at once, like a clear.
      if (next === '') return commit(next);
      pending.current = next;
      timer.current = setTimeout(() => commit(next), delayMs);
    },
    flush: () => {
      if (pending.current !== null) commit(pending.current);
    },
    replace: (next: string) => {
      setDraft(next);
      commit(next);
    },
  };
}
